import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 4
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = [row for row in reader if row and any(cell.strip() for cell in row)]
    if not records:
        return {"columns": [], "rows": []}

    header_index = next(
        (i for i, row in enumerate(records) if len(row) == expected_width),
        0,
    )
    columns = list(records[header_index])

    if len(columns) < expected_width:
        columns.extend([""] * (expected_width - len(columns)))
    elif len(columns) > expected_width:
        columns = columns[: expected_width - 1] + [
            ";".join(columns[expected_width - 1 :])
        ]

    width = len(columns)
    rows = []
    for record in records[header_index + 1 :]:
        row = list(record)
        if len(row) < width:
            row.extend([""] * (width - len(row)))
        elif len(row) > width:
            row = row[: width - 1] + [";".join(row[width - 1 :])]
        rows.append(row)

    return {"columns": columns, "rows": rows}
